```js
class Carrito {
  constructor() { this.lineas = [] }
  agregar(producto, cantidad) {
    const linea = this.lineas.find((l) => l.producto === producto)
    const nueva = (linea?.cantidad ?? 0) + cantidad
    if (nueva > producto.stock) throw new Error(`Sin stock de ${producto.nombre}`)
    if (linea) linea.cantidad = nueva
    else this.lineas.push({ producto, cantidad })
  }
  quitar(nombre) { this.lineas = this.lineas.filter((l) => l.producto.nombre !== nombre) }
  total() { return this.lineas.reduce((s, l) => s + l.producto.precio * l.cantidad, 0) }
  confirmar() {
    if (this.lineas.some((l) => l.cantidad > l.producto.stock)) throw new Error('Stock cambió')
    this.lineas.forEach((l) => l.producto.vender(l.cantidad))
    this.lineas = []
  }
}
```
El carrito delega en producto.vender porque la regla 'no vender sin stock' pertenece al producto: si mañana cambia, se corrige en un solo lugar.

