const esAlfanum = (c) => /[a-z0-9]/i.test(c)
function esPalindromo(texto) {
  let i = 0
  let j = texto.length - 1
  while (i < j) {
    if (!esAlfanum(texto[i])) { i++; continue }
    if (!esAlfanum(texto[j])) { j--; continue }
    if (texto[i].toLowerCase() !== texto[j].toLowerCase()) return false
    i++; j--
  }
  return true
} // O(n) tiempo, O(1) espacio; evita crear el string limpio e invertido
